import {soundscape} from './soundscape.js';
import {getArena} from './arenas.js';
import {roster,getFighter} from './roster.js';
import {portrait,drawStreet,hero,drawEnemy,drawEffects,setNeighborhood} from './street-art.js';
import {StreetRun,stages} from './streets.js';
import {campaignSides,bossFor,eligibleFighters,fighterSide} from './campaign.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),dialog=$('dialog');
let campSide='left',initialStage=0,selected=['lula','janja'],selecting=0,mode='solo',run=null,paused=false,sound=false,audioContext,last=0,accumulator=0,sceneTime=0,research={profiles:[]},shaking=0,overlayKey='';
const keys=new Set(),images=new Map(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let neighborhoodSources={sources:[]};fetch('neighborhood-sources.json').then(r=>r.json()).then(v=>{neighborhoodSources=v}).catch(()=>{neighborhoodSources.error=true});
let photoCredits={photos:[]};fetch('photo-credits.json').then(r=>r.json()).then(v=>{photoCredits=v}).catch(()=>{});
fetch('research.json').then(r=>r.json()).then(r=>{research=r}).catch(()=>{research.error=true});
function ensureSprite(id){if(images.has(id))return images.get(id);const image=new Image();image.src='assets/sprites/'+id+'.png?v=20261020-6';images.set(id,image);return image}selected.forEach(ensureSprite);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function source(url,label='Abrir fonte ↗'){return /^https:\/\//.test(url||'')?`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`:''}
function beep(){soundscape.fx('ui')}
function toast(text){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=text;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function renderRoster(){$('roster').innerHTML=eligibleFighters(campSide).map(f=>`<button class="fighter ${selected[0]===f.id?'selected-p1':''} ${selected[1]===f.id&&mode==='local'?'selected-p2':''}" data-fighter="${f.id}" aria-label="Selecionar ${f.name}" aria-pressed="${selected[selecting]===f.id}">${selected[0]===f.id?'<span class="player-badge">1P</span>':''}${selected[1]===f.id&&mode==='local'?'<span class="player-badge second">2P</span>':''}${portrait(f)}<span class="fighter-name">${f.short.toUpperCase()}</span></button>`).join('');renderCard(getFighter(selected[selecting]));document.querySelectorAll('[data-player]').forEach(b=>{b.classList.toggle('active',+b.dataset.player===selecting);b.hidden=+b.dataset.player===1&&mode!=='local'})}
function renderCard(f){$('fighter-card').innerHTML=`<div class="portrait">${portrait(f)}</div><p class="eyebrow">${selecting===0?'SEU PERSONAGEM / 1P':'SEU PARCEIRO / 2P'}</p><h3>${f.name.toUpperCase()}</h3><p class="role">${f.style}</p>${[['VELOCIDADE',f.speed],['IMPACTO',f.power],['DEFESA',f.guard]].map(([n,v])=>`<div class="stat"><span>${n}</span><i><b style="width:${v*20}%"></b></i></div>`).join('')}<div class="move"><small>H · ESPECIAL / 25 BRASA</small><h4>${f.special.toUpperCase()}</h4><p>${f.specialDescription}</p><small>R · SUPER / 100 BRASA</small><p>Uma explosão de impacto atinge os inimigos próximos na mesma faixa da rua.</p></div><button id="read-profile">HISTÓRICO, FALAS & POSIÇÕES ↗</button>`;$('read-profile').onclick=()=>openResearch(f.id)}
function selectFighter(id){selected[selecting]=id;ensureSprite(id);renderRoster();beep(410,.04);if(run)toast('Personagem escolhido para a próxima campanha.');renderHUD()}
$('roster').addEventListener('click',e=>{const b=e.target.closest('[data-fighter]');if(b)selectFighter(b.dataset.fighter)});
document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{selecting=+b.dataset.player;renderRoster()});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;if(mode==='solo')selecting=0;document.querySelectorAll('[data-mode]').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b)});renderRoster();renderHUD();if(run)toast('Modo escolhido para a próxima campanha.')});
$('random').onclick=()=>selectFighter(eligibleFighters(campSide)[Math.floor(Math.random()*eligibleFighters(campSide).length)].id);
function event(type,data={}){if(type==='attack'){soundscape.fx('whoosh');if(data.kind==='special'||data.kind==='super')soundscape.fx(data.kind)}if(type==='hit'||type==='hurt'){soundscape.fx(data.kind==='kick'?'kick':'hit',data.damage?data.damage/14:1);if(!reduced)shaking=.12}if(type==='boss-special')beep(280,.2,'sawtooth');if(type==='block')soundscape.fx('block');if(type==='jump')soundscape.fx('jump');if(type==='land')soundscape.fx('land',(data.speed||500)/650);if(type==='step')soundscape.fx('step');if(type==='break')soundscape.fx('break');if(type==='pickup')soundscape.fx('pickup');if(type==='dry')toast('Sem Brasa suficiente. Acerte golpes ou encontre energia nas caixas.');}
function start(){soundscape.unlock(true);selected.forEach(ensureSprite);ensureSprite(campaignSides[campSide].master);run=new StreetRun(getFighter(selected[0]),getFighter(selected[1]),mode,event,Math.random,getArena(),campSide,initialStage);paused=false;keys.clear();overlayKey='';accumulator=0;$('welcome').classList.add('hidden');$('arena').classList.add('playing');canvas.focus();renderHUD();overlays()}
$('start').onclick=start;
function text(id,value){const e=$(id);if(e.textContent!==String(value))e.textContent=value}
function renderHUD(){const coop=(run?.mode||mode)==='local';$('partner-hud').classList.toggle('hidden',!coop);$('solo-hud').classList.toggle('hidden',coop);for(let i=0;i<2;i++){const p=run?.players[i],prefix='p'+(i+1);text(prefix+'-name',(p?.data||getFighter(selected[i])).short.toUpperCase());$(prefix+'-health').style.width=(p?.hp??100)+'%';$(prefix+'-meter').style.width=(p?.meter??35)+'%';text(prefix+'-energy',Math.floor(p?.meter??35));text(prefix+'-lives','♥ '.repeat(p?.lives??3).trim()||'SEM VIDAS')}
 text('score',String(run?.score||0).padStart(6,'0'));text('kill-count',run?.kills||0);text('stage-number','FASE '+String((run?.stageIndex??initialStage)+1).padStart(2,'0')+' / '+String(stages.length).padStart(2,'0'));text('stage-name',run?.stage.name||stages[initialStage].name);const place=run?.arenaMission?null:(run?.stage||stages[initialStage]);text('stage-place',place?`${place.city.toUpperCase()} / ${place.uf} · ${place.region.toUpperCase()}`:'MISSÃO ESPECIAL');text('status',paused?'PAUSA NA CALÇADA':!run?'A CIDADE ESTÁ ESPERANDO':run.state==='fight'?`${run.livingEnemies.length} INIMIGOS NA ÁREA`:run.state==='victory'?'AS RUAS SÃO SUAS':'A NOITE CONTINUA');text('wave-label',run?`GRUPO ${run.wave}/3 · ${run.waveActive?'ABRA CAMINHO':'SIGA EM FRENTE'}`:'O BAIRRO NÃO DORME');$('route-progress').style.width=((run?.progress||0)*100)+'%';const e=run?.target;$('enemy-hud').classList.toggle('hidden',!e||e.dead||!run||run.state!=='fight');if(e){text('enemy-name',e.data.name);$('enemy-health').style.width=e.hp/e.maxHp*100+'%'}$('street-notice').classList.toggle('hidden',!run||run.noticeTime<=0||run.state!=='fight'||paused);if(run)text('street-notice',run.notice);$('go').classList.toggle('hidden',!run||run.waveActive||run.state!=='fight'||paused)}
function overlays(){const state=!run?'welcome':paused?'paused':run.state,key=state+(run?.stageIndex||0);if(key===overlayKey)return;overlayKey=key;const overlay=$('overlay');if(state==='welcome'||state==='fight'){overlay.classList.add('hidden');return}overlay.classList.remove('hidden');let kicker='',title='',description='',buttons='';if(state==='intro'){kicker=run.arenaMission?'MISSÃO ESPECIAL · 3 ONDAS':'FASE '+String(run.stageIndex+1).padStart(2,'0')+' / '+String(stages.length).padStart(2,'0');title=run.stage.name;description=run.arenaMission?run.stage.subtitle:`${run.stage.city} / ${run.stage.uf} · ${run.stage.region}. ${run.stage.subtitle} Chefão: ${run.boss.name} (${campaignSides[run.boss.campSide].label.toLowerCase()}).`;}if(state==='paused'){kicker='RESPIRE. A NOITE AINDA NÃO ACABOU.';title='PAUSA NA CALÇADA';description='ESC para voltar às ruas.';buttons='<button data-action="resume">CONTINUAR →</button><button data-action="restart">RECOMEÇAR</button><button data-action="menu">ESCOLHER PERSONAGEM</button>'}if(state==='stageclear'){kicker='CHEFE DERROTADO · BAIRRO LIBERADO';title='A RUA É SUA.';description=`${run.score.toLocaleString('pt-BR')} pontos. O próximo desafio espera em ${stages[run.stageIndex+1].name}.`;buttons='<button data-action="next">PRÓXIMA FASE →</button>'}if(state==='victory'){kicker=run.arenaMission?'3 ONDAS CONCLUÍDAS · ARENA LIBERADA':`${stages.length-run.startStage} FASES CONCLUÍDAS · ROTA ENCERRADA`;title='ATÉ O SOL NASCER.';description=`${run.arenaMission?'Você dominou a arena.':'Você concluiu a rota pelo Brasil.'} ${run.kills} inimigos derrotados · ${run.score.toLocaleString('pt-BR')} pontos.`;buttons='<button data-action="restart">MAIS UMA NOITE →</button><button data-action="menu">ESCOLHER PERSONAGEM</button>'}if(state==='gameover'){kicker='FIM DA LINHA · VIDAS ESGOTADAS';title='A RUA COBROU.';description=`${run.score.toLocaleString('pt-BR')} pontos · ${run.kills} inimigos derrotados. Tente outro caminho, outro especial ou uma dupla.`;buttons='<button data-action="restart">TENTAR DE NOVO →</button><button data-action="menu">ESCOLHER PERSONAGEM</button>'}$('overlay-kicker').textContent=kicker;$('overlay-title').textContent=title;$('overlay-description').textContent=description;$('overlay-actions').innerHTML=buttons}
$('overlay-actions').onclick=e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='resume'){paused=false;canvas.focus()}if(a==='restart')start();if(a==='next'){run.nextStage();keys.clear();canvas.focus()}if(a==='menu'){run=null;paused=false;keys.clear();$('welcome').classList.remove('hidden');$('arena').classList.remove('playing');$('overlay').classList.add('hidden');document.querySelector('.selection').scrollIntoView({behavior:reduced?'instant':'smooth'})}renderHUD();overlays()};
function pause(){if(run&&['fight','intro'].includes(run.state)){paused=!paused;keys.clear()}}
const actions={KeyF:[0,'punch'],KeyG:[0,'kick'],KeyH:[0,'special'],KeyR:[0,'super'],KeyJ:[1,'punch'],KeyK:[1,'kick'],KeyL:[1,'special'],KeyU:[1,'super'],Numpad1:[1,'punch'],Numpad2:[1,'kick'],Numpad3:[1,'special'],Numpad5:[1,'super']};
const gameKeys=new Set(['KeyW','KeyA','KeyS','KeyD','Space','ShiftLeft','ShiftRight','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter','Escape','Numpad0','NumpadDecimal','KeyO','KeyP',...Object.keys(actions)]);
window.addEventListener('keydown',e=>{if(dialog.open||!gameKeys.has(e.code)||e.target.matches('input,textarea,select'))return;if(e.target.closest('button,a')&&(e.code==='Enter'||e.code==='Space'))return;if(!run&&e.code!=='Enter')return;e.preventDefault();if(e.repeat)return;if(e.code==='Enter'&&!run){start();return}if(e.code==='Escape'){pause();return}if(paused||!run)return;keys.add(e.code);const a=actions[e.code];if(a)run.attack(...a)});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(run&&['fight','intro'].includes(run.state))paused=true});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(run&&['fight','intro'].includes(run.state))paused=true}});
function inputs(){return [{left:keys.has('KeyA'),right:keys.has('KeyD'),up:keys.has('KeyW'),down:keys.has('KeyS'),jump:keys.has('Space'),block:keys.has('ShiftLeft')||keys.has('ShiftRight')},{left:keys.has('ArrowLeft'),right:keys.has('ArrowRight'),up:keys.has('ArrowUp'),down:keys.has('ArrowDown'),jump:keys.has('KeyO')||keys.has('Numpad0'),block:keys.has('KeyP')||keys.has('NumpadDecimal')}]}
document.querySelectorAll('[data-hold],[data-attack]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(!run||paused||dialog.open)return;if(b.dataset.hold)keys.add(b.dataset.hold);if(b.dataset.attack)run.attack(0,b.dataset.attack)};const release=()=>{if(b.dataset.hold)keys.delete(b.dataset.hold)};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release});
function draw(){ctx.save();if(shaking>0&&!reduced)ctx.translate((Math.random()-.5)*7,(Math.random()-.5)*4);drawStreet(ctx,run,sceneTime,reduced);const preview=selected.slice(0,mode==='local'?2:1).map((id,i)=>({data:getFighter(id),index:i,x:340+i*180,lane:530+i*20,y:0,vx:0,facing:1,stun:0,invincible:0}));const entities=run?[...run.enemies,...run.players]:preview;for(const f of [...entities].sort((a,b)=>a.lane-b.lane)){if(f.enemy)drawEnemy(ctx,f,sceneTime,run.camera);else hero(ctx,f,ensureSprite(f.data.id),sceneTime,run?.camera||0)}if(run){drawEffects(ctx,run);for(const p of run.players)if(p.combo>=2&&p.comboClock>0){ctx.font='italic 800 29px "Barlow Condensed",Arial';ctx.fillStyle=p.index?'#c6e68c':'#ffc080';ctx.textAlign='left';ctx.fillText(`${p.combo} HITS`,70+p.index*1000,177)}}ctx.restore()}
function frame(timestamp){soundscape.setRunning(!!run&&!paused&&!dialog.open);const dt=Math.min((timestamp-last)/1000||0,.1);last=timestamp;if(!paused&&!dialog.open)sceneTime+=dt;shaking=Math.max(0,shaking-dt);if(run&&!paused&&!dialog.open){accumulator+=dt;while(accumulator>=1/60){run.update(1/60,inputs());accumulator-=1/60}}else accumulator=0;draw();renderHUD();overlays();requestAnimationFrame(frame)}
function openDialog(label,html){if(run&&['fight','intro'].includes(run.state))paused=true;keys.clear();$('dialog-label').textContent=label;$('dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
function controls(){openDialog('STREETS OF RAGE BRASA / MANUAL DAS RUAS',`<h2>A CIDADE É O CENÁRIO.</h2><p>Uma campanha de sete fases nas cinco regiões do Brasil, em rolagem lateral. Escolha uma fase inicial na rota dos bairros e siga até o final. Escolher ESQUERDA traz chefões de direita e Flávio Bolsonaro no final; escolher DIREITA traz chefões de esquerda e Lula no final. Os chefões regionais são personagens originais. Avance para a direita, derrote cada grupo e enfrente o chefe do bairro. Para acertar um inimigo, fique na mesma faixa da rua e vire na direção dele. O ponto de exclamação avisa que um ataque está chegando: saia da faixa, salte ou defenda.</p><div class="controls-grid">${[[1,[['Mover na rua','W A S D'],['Saltar','Espaço'],['Soco / chute','F / G'],['Especial · 25 Brasa','H'],['Super · 100 Brasa','R'],['Defender','Shift']]],[2,[['Mover na rua','↑ ← ↓ →'],['Saltar','O / Num 0'],['Soco / chute','J / K ou Num 1 / 2'],['Especial · 25 Brasa','L / Num 3'],['Super · 100 Brasa','U / Num 5'],['Defender','P / Num decimal']]]].map(([n,rows])=>`<div><h3>JOGADOR ${n}</h3>${rows.map(([label,k])=>`<div class="key-row"><span>${label}</span><span>${k}</span></div>`).join('')}</div>`).join('')}</div><h3>ENCONTRE SEU CAMINHO</h3><p>W e S movem para o fundo e para a frente da rua. O salto usa uma tecla separada. Barris escondem recuperação de 35 de vida; caixas guardam 35 de Brasa. Quebre com socos ou chutes e passe por cima do item para recolher. Acertar golpes também carrega energia. Cada jogador começa com três vidas e reaparece protegido depois de cair.</p><h3>ESPECIAIS & DUPLA</h3><p>Cada personagem mantém seu especial: projétil, avanço, ascendente, impacto de área ou escudo. O super atinge os inimigos na mesma faixa, até uma distância maior, em qualquer direção. No cooperativo, os dois jogadores avançam juntos, dividem a câmera e enfrentam mais inimigos. Não há dano entre parceiros.</p><p>ESC pausa. Ao sair da janela ou abrir o dossiê, o jogo pausa. Alguns teclados limitam teclas simultâneas; use os comandos alternativos do teclado numérico se necessário. Em telas de toque, use os botões abaixo do jogo para o jogador 1.</p>`)}
function openResearch(id=selected[selecting]){const f=getFighter(id),p=research.profiles.find(p=>p.id===id),photo=photoCredits.photos.find(p=>p.id===id);openDialog('STREETS OF RAGE BRASA / DOSSIÊ DO ELENCO',`<h2>POR TRÁS DO PERSONAGEM.</h2><p>Histórico, posições e falas públicas, pesquisados em 20/10/2026. Fontes partidárias registram as posições dos próprios autores. As citações foram conferidas em textos publicados; áudio e timestamps ainda não foram conferidos.</p><div class="research-nav">${roster.map(r=>`<button data-profile="${r.id}" class="${id===r.id?'active':''}">${r.short}</button>`).join('')}</div><article class="research-body">${photo?`<div class="research-photo">${portrait(f,true)}<div><span class="tag">FOTOGRAFIA DE REFERÊNCIA</span><p>${escape(photo.credit)} · ${escape(photo.license)}</p>${source(photo.sourcePage,'Origem da fotografia ↗')}<p>${escape(photo.notes)}</p><p>Retrato real. Corpo e poses de luta reconstruídos por IA a partir da referência; cenas fictícias.</p></div></div>`:''}<span class="tag">PERFIL PÚBLICO / ${f.style.toUpperCase()}</span><h3>${f.name.toUpperCase()}</h3>${p?`<p>${escape(p.history)}</p>${(p.historySources||[]).map(s=>source(s.url,s.titulo||'Referência biográfica ↗')).join(' · ')}<h3>POSIÇÕES & ATUAÇÃO PÚBLICA</h3><ul>${p.positions.map(v=>`<li><strong>${escape(v.date)} · ${escape(v.period)}</strong><br>${escape(v.text)}<br>${source(v.url,v.title||'Fonte do registro ↗')}</li>`).join('')}</ul>${p.quote?`<div class="source-block"><span class="tag">FALA REAL · ${escape(p.quote.date)}</span><blockquote>“${escape(p.quote.text)}”</blockquote><p>${escape(p.quote.context)}</p>${source(p.quote.url)}</div>`:'<p>Sem fala literal verificada para este perfil.</p>'}${p.debateQuote?`<div class="source-block"><span class="tag">FALA REAL / DEBATE BAND · 18/10/2026</span><blockquote>“${escape(p.debateQuote.text)}”</blockquote><p>${escape(p.debateQuote.context)}</p>${source(p.debateQuote.url)}</div>`:''}<h3>DO PERFIL PARA O ARCADE</h3><p>Referências criativas: ${escape((p.motifs||[]).join(' · '))}. O especial <strong>${f.special}</strong> é uma interpretação fictícia, sem atribuição de atos reais ao personagem.</p>${p.notes?.length?`<h3>CONTEXTO & LIMITES</h3><ul>${p.notes.map(n=>`<li>${escape(n)}</li>`).join('')}</ul>`:''}`:`<p>${research.error?'Não foi possível carregar o dossiê. Recarregue a página.':'Carregando pesquisa… feche e abra este painel em instantes.'}</p>`}<h3>REFERÊNCIAS DO ELENCO</h3><p>O elenco satírico foi desenvolvido com referências públicas. A campanha recria artisticamente sete locais reais. Chefões regionais são originais; Lula e Flávio Bolsonaro aparecem em confrontos finais satíricos. Isso não indica vínculos com crime ou controle dos bairros. As falas do dossiê estão identificadas com sua data e contexto.</p>${source('https://www.band.com.br/politica/eleicoes/ao-vivo-assista-ao-debate-na-band-entre-flavio-bolsonaro-e-lula','Band · íntegra e contexto ↗')}<p>O dossiê reúne fontes públicas pesquisadas. Paródia independente, sem vínculo com emissoras, partidos ou franquias de jogos. Violência estilizada; indicação de 16 anos é sugestão editorial, sem classificação oficial.</p></article>`);$('dialog-content').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{openResearch(b.dataset.profile)})}
document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>b.dataset.dialog==='controls'?controls():openResearch());$('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{keys.clear();canvas.focus()});
$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',sound);$('sound').innerHTML=sound?'SOM ON <span>◉</span>':'SOM OFF <span>◌</span>';beep(550,.1,'triangle')};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.game-shell').requestFullscreen()}catch{toast('Tela cheia indisponível neste navegador.')}};
function renderCampaign(){
 const side=campaignSides[campSide];document.querySelectorAll('[data-side]').forEach(b=>{const active=b.dataset.side===campSide;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 text('side-context',`Seu lado: ${side.label}. Chefões de ${side.opponent.toLowerCase()}. Confronto master: ${getFighter(side.master).name}.`);
 $('neighborhoods').innerHTML=stages.map((stage,i)=>{const boss=bossFor(stage,campSide);return `<button class="neighborhood ${i===initialStage?'active':''}" data-neighborhood="${i}" aria-pressed="${i===initialStage}" aria-label="Começar em ${escape(stage.name)}, ${escape(stage.city)}, chefão ${escape(boss.name)}"><div class="neighborhood-picture"><img src="${stage.image}" alt="Cenário artístico de ${escape(stage.name)}" loading="lazy"><span>${String(i+1).padStart(2,'0')} / ${stage.region.toUpperCase()}</span></div><div class="neighborhood-copy"><small>${stage.city.toUpperCase()} / ${stage.uf}</small><strong>${stage.name}</strong><p>${stage.landmark}</p><p class="wardrobe-note">${stage.wardrobe}</p><span>${stage.master?'MASTER':'CHEFÃO'} · ${escape(boss.name)}</span></div></button>`}).join('');
 setNeighborhood(initialStage);
}
document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{campSide=b.dataset.side;const pool=eligibleFighters(campSide);selected=selected.map((id,i)=>fighterSide(id)&&fighterSide(id)!==campSide?pool[Math.min(i,pool.length-1)].id:id);selected.forEach(ensureSprite);renderCampaign();renderRoster();renderHUD();if(run)toast('Lado escolhido para a próxima campanha.')});
$('neighborhoods').onclick=e=>{const b=e.target.closest('[data-neighborhood]');if(!b)return;initialStage=+b.dataset.neighborhood;renderCampaign();renderHUD();if(run)toast('Fase inicial escolhida para a próxima campanha.');else{canvas.scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'})}};
$('neighborhood-info').onclick=()=>{const evidence=neighborhoodSources;openDialog('STREETS OF RAGE BRASA / BAIRROS & FONTES',`<h2>SETE ENDEREÇOS REAIS.</h2><p>${escape(evidence.methodology||'Carregando referências. Feche e reabra este painel em instantes.')}</p>${evidence.error?'<p>Não foi possível carregar as fontes. Recarregue a página.</p>':''}${stages.map(stage=>`<article class="neighborhood-source"><span class="tag">${stage.region.toUpperCase()} · ${stage.city.toUpperCase()} / ${stage.uf}</span><h3>${stage.name}</h3><p>${stage.landmark}</p><p><strong>Figurino desta fase:</strong> ${stage.wardrobe} Escolhas artísticas para o clima do cenário; não descrevem todos os moradores.</p>${stage.sourceIds.map(id=>{const sourceData=evidence.sources.find(v=>v.id===id);return sourceData?`<div class="source-block">${source(sourceData.url,sourceData.title+' ↗')}<p><strong>${escape(sourceData.period)}</strong> · ${escape(sourceData.kind)}</p><p>${escape(sourceData.note)}</p></div>`:''}).join('')}<p>Chefão nesta rota: <strong>${escape(bossFor(stage,campSide).name)}</strong>, ${campaignSides[bossFor(stage,campSide).campSide].label.toLowerCase()}. ${stage.master?'Figura pública em confronto satírico.':'Personagem original, sem vínculo com pessoas ou organizações locais.'}</p></article>`).join('')}<h3>O QUE PERTENCE À FICÇÃO</h3><p>${escape(evidence.fiction||'Combates e chefões regionais são ficção.')}</p>`)};
renderCampaign();renderRoster();renderHUD();requestAnimationFrame(frame);

